def list_profiles_in(path):
    """list profiles in a given root directory"""
    profiles = []
    files = os.scandir(path)
    for f in files:
        if f.is_dir() and f.name.startswith('profile_'):
            profiles.append(f.name.split('_', 1)[-1])
    return profiles
