            environ = context.get('env')
            curr_loc = environ.get('pywb_lang', '')
            request_uri = environ.get('REQUEST_URI', environ.get('PATH_INFO'))
            if curr_loc:
                return request_uri.replace(curr_loc, locale, 1)
            app_prefix = environ.get('pywb.app_prefix', '')
