        put_record = params.get('put_record')
        if put_record and method in ('PUT', 'POST'):
            return self._put_record(request_uri,
                                    input_buff,
                                    put_record,
                                    headers,
                                    params,
                                    start_response)
        skipping = any(x.skip_request(path, headers) for x in self.skip_filters)
        req_is_wrapped = False
        if not skipping:
            req_stream = ReqWrapper(input_buff,
                                    headers,
                                    params,
                                    self.create_buff_func)
            req_is_wrapped = True
        else:
            req_stream = input_buff
        data = None
        if input_buff:
            data = req_stream
        try:
            res = requests.request(url=self.upstream_host + request_uri,
                                   method=method,
                                   data=data,
                                   headers=headers,
                                   allow_redirects=False,
                                   stream=True)
            res.raise_for_status()
        except Exception as e:
            if req_is_wrapped:
                no_except_close(req_stream.out)
            return self.send_error(e, start_response)
        if not skipping:
            skipping = any(x.skip_response(path,
                                           req_stream.headers,
                                           res.headers,
                                           params)
                           for x in self.skip_filters)
        if not skipping:
            resp_stream = RespWrapper(res.raw,
                                      res.headers,
                                      req_stream,
                                      params,
                                      self.write_queue,
                                      path,
                                      self.create_buff_func)
        else:
            resp_stream = res.raw
            if req_is_wrapped:
                no_except_close(req_stream.out)
        resp_iter = StreamIter(resp_stream)
        res.headers.pop('Transfer-Encoding', '')
        start_response('200 OK', list(res.headers.items()))
        return resp_iter
    def _write_to_file(self):
        skipping = False
        try:
            if self.interrupted:
                skipping = True
            if not skipping:
                entry = (self.req.headers, self.req.out,
                         self.headers, self.out, self.params)
                self.queue.put(entry)
        except Exception:
            traceback.print_exc()
            skipping = True
        finally:
            if skipping:
                no_except_close(self.out)
                no_except_close(self.req.out)
            no_except_close(self.req)
            self.req = None
                no_except_close(r.raw)
            no_except_close(r.raw)
            no_except_close(r.raw)
            no_except_close(self.body)
                    no_except_close(headers.raw_stream)
                    no_except_close(payload.raw_stream)
            no_except_close(headers.raw_stream)
            no_except_close(upstream_res)
                no_except_close(upstream_res)
    def _close_file(self, fh):
        try:
            if os.name != 'nt':
                portalocker.lock(fh, portalocker.LOCK_UN)
            return True
        except Exception as e:
            print(e)
            return False
        finally:
            no_except_close(fh)

