            samesite = None
        kwargs["samesite"] = samesite
        kwargs["secure"] = settings().getBoolean(["server", "cookies", "secure"])
        if key == current_app.config.get("REMEMBER_COOKIE_NAME", REMEMBER_COOKIE_NAME):
