def is_target_path_valid(path: pathlib.Path, target: pathlib.Path) -> bool:
    try:
        if path.is_absolute():
            target.resolve().relative_to(path)
        else:
            target.resolve().relative_to(pathlib.Path(os.getcwd()).joinpath(path))
    except ValueError:
        return False
    return True

