                    self.validate_chunk_end = False
            elif not self.all_chunks_received:
                s = self.control_line + s
                pos = s.find(b"\r\n")
                if pos < 0:
                    self.control_line = s
                    s = b""
                else:
                    line = s[:pos]
                    s = s[pos + 2 :]
                    self.control_line = b""
                    line = line.strip()
                    if line:
                        semi = line.find(b";")
                        if semi >= 0:
                            line = line[:semi]
