    def get_user_status(self, msg):
        status = msg.status
        if status < 0:
            return
        user = msg.user
        iterator = self.user_iterators.get(user)
        if iterator is None:
            return
        if status == int(self.usersmodel.get_value(iterator, 10)):
            return
        notify = self.usersmodel.get_value(iterator, 6)
        if notify:
            if status == 1:
