    def _data(self, days):
        """
        Return number of backups per days including failure.
        """
        def _key(d):
            return time.strftime(str(d).split('T')[0])
        base = RdiffTime().set_time(0, 0, 0) - datetime.timedelta(days=days)
        data = {_key(base + datetime.timedelta(days=i)): [] for i in range(0, days + 1)}
        success = {_key(base + datetime.timedelta(days=i)): 0 for i in range(0, days + 1)}
        failure = success.copy()
        for repo in self.app.currentuser.repo_objs:
            if len(repo.session_statistics):
                for stat in repo.session_statistics[base:]:
                    key = _key(stat.date)
                    if key not in success:
                        continue
                    success[key] = success.get(key, 0) + 1
                    data[key].append(stat)
                    if stat.errors:
                        failure[key] += 1
        return {
            'backup_count': [
                {'name': _('Successful Backup'), 'data': success},
                {'name': _('Backup with errors'), 'data': failure},
            ],
            'data': data,
        }
    def status(self):
        """Check if a backup is in progress for the current repo."""
        try:
            for current_mirror in self.current_mirror:
                pid = current_mirror.extract_pid()
                try:
                    p = psutil.Process(pid)
                    if any('rdiff-backup' in c for c in p.cmdline()):
                        return ('in_progress', _('A backup is currently in progress to this repository.'))
                except psutil.NoSuchProcess:
                    logger.debug('pid [%s] does not exists', pid)
            if len(self.current_mirror) > 1 or len(self.current_mirror) == 0:
                self._status = ('interrupted', _('The previous backup seams to have failed.'))
                return self._status
