def do_format_lastupdated(value, now=None):
    """
    Used to format date as "Updated 10 minutes ago".
    Value could be a RdiffTime or an epoch as int.
    """
    if not value:
        return ""
    now = librdiff.RdiffTime(now)
    delta = now.epoch() - (value.epoch() if isinstance(value, librdiff.RdiffTime) else value)
    delta = datetime.timedelta(seconds=delta)
    if delta.days > 365:
        return _('%d years ago') % (delta.days / 365)
    if delta.days > 60:
        return _('%d months ago') % (delta.days / 30)
    if delta.days > 7:
        return _('%d weeks ago') % (delta.days / 7)
    elif delta.days > 1:
        return _('%d days ago') % delta.days
    elif delta.seconds > 3600:
        return _('%d hours ago') % (delta.seconds / 3600)
    elif delta.seconds > 60:
        return _('%d minutes ago') % (delta.seconds / 60)
    return _('%d seconds ago') % delta.seconds
    def _data(self, days):
        """
        Return number of backups per days including failure.
        """
        def _key(d):
            return time.strftime(str(d).split('T')[0])
        base = RdiffTime().set_time(0, 0, 0) - datetime.timedelta(days=days)
        data = {_key(base + datetime.timedelta(days=i)): [] for i in range(0, days + 1)}
        success = {_key(base + datetime.timedelta(days=i)): 0 for i in range(0, days + 1)}
        failure = success.copy()
        for repo in self.app.currentuser.repo_objs:
            if len(repo.session_statistics):
                for stat in repo.session_statistics[base:]:
                    key = _key(stat.date)
                    if key not in success:
                        continue
                    success[key] = success.get(key, 0) + 1
                    data[key].append(stat)
                    if stat.errors:
                        failure[key] += 1
        return {
            'backup_count': [
                {'name': _('Successful Backup'), 'data': success},
                {'name': _('Backup with errors'), 'data': failure},
            ],
            'data': data,
        }
