class DetachedIntegrityCheckedFile(IntegrityCheckedFile):
    def integrity_protected_file(self, tmpdir):
        path = str(tmpdir.join("file"))
        with DetachedIntegrityCheckedFile(path, write=True) as fd:
            fd.write(b"foo and bar")
