def set_ec(ec):
    """
    Sets the exit code of the program, if an exit code higher or equal than this is set, this does nothing. This
    makes EXIT_ERROR override EXIT_WARNING, etc..
    ec: exit code to set
    """
    global exit_code
    exit_code = max(exit_code, ec)
    return exit_code
